#define LORA_RX 16
#define LORA_TX 17
#define M0 18
#define M1 19
#define AUX 4

HardwareSerial LoRa(2);

void setup() {
  Serial.begin(115200);

  pinMode(M0, OUTPUT);
  pinMode(M1, OUTPUT);
  pinMode(AUX, INPUT);

  digitalWrite(M0, HIGH);
  digitalWrite(M1, HIGH);

  delay(100);

  LoRa.begin(9600, SERIAL_8N1, LORA_RX, LORA_TX);

  Serial.println("EBYTE E32 MODULE TEST");

  // Wait for module to become ready
  delay(1000);

  byte command[] = {0xC1, 0xC1, 0xC1};
  LoRa.write(command, 3);

  delay(500);

  Serial.print("AUX STATUS: ");
  Serial.println(digitalRead(AUX));

  Serial.println("Module response:");

  if (LoRa.available()) {
    while (LoRa.available()) {
      byte data = LoRa.read();
      if (data < 16) Serial.print("0");
      Serial.print(data, HEX);
      Serial.print(" ");
    }
    Serial.println();
    Serial.println("MODULE RESPONDED!");
  } else {
    Serial.println("NO RESPONSE");
  }
}

void loop() {
}
